style.css:
@-moz-document domain("last.fm") {
:root { color-scheme: dark; --lf-bg:#101010; --lf-panel:#191919; --lf-line:#303030; --lf-text:#f1f1f1; --lf-muted:#b0b0b0; --lf-accent:#ffffff; }
  html, body, .main-content, .page-content, .container, .content, .content-top,
  .content-top-lower, .header--overview, .header--sub-page, .header--overview .container,
  .header--sub-page .container, .user-dashboard, .user-dashboard .container,
  .user-dashboard-layout--version-5 .main-content,
  .user-dashboard-layout--version-5 .user-dashboard .container,
  .footer-wrapper, .site-footer, .secondary-nav, .chartlist-row,
  .chartlist-row:hover, .chartlist td, .col-main, .col-sidebar,
  .user-dashboard-module, .report-box-container, .listening-report-brick,
  .listening-report-brick-inner, .personal-stats, .personal-stats-item,
  .user-dashboard-banner, .user-dashboard-comparison, .listening-report-promo,
  .user-dashboard-history-subscribe-banner-cta, .user-dashboard-upsell-fade-out,
  .grid-items--fade-out::after { background-color:var(--lf-bg) !important; }
  body, .main-content, .content, .container, .chartlist, .chartlist td,
  .chartlist-name a, .chartlist-artist a, .chartlist-album a,
  .header-metadata-display, .header-metadata-display a, .header-metadata-title,
  .header-title, .header-title a, .header-title-secondary,
  .metadata-display, .metadata-title, .user-dashboard-module,
  .personal-stats, .personal-stats-item, .listening-report-brick,
  .listening-report-brick a, .shout, .shout-user a,
  .secondary-nav-item-link, .secondary-nav-item-link:visited,
  h1,h2,h3,h4,h5,h6,p,li,td,th,label,small,strong { color:var(--lf-text) !important; }
  .chartlist-timestamp, .header-info-secondary, .header-metadata-title,
  .metadata-title, .shout-timestamp, .user-dashboard-legend-item,
  .user-dashboard-date, .listening-report-promo-date,
  .chartlist-index, .user-dashboard-small-data-point-label { color:var(--lf-muted) !important; }
  /* White actions, navigation, progress bars and loved hearts. */
  .btn-primary, .btn-add, .btn-add-sm, .header .secondary-nav-item-link--active::after,
  .secondary-nav-item-link--active::after,
  .masthead-search-submit { background-color:var(--lf-accent) !important; }
  .btn-primary, .btn-add, .btn-add-sm { color:#111 !important; }
  /* Remove the grey gradient and rectangular boxes on the current track. */
  .chartlist-row--now-scrobbling,
  .chartlist-row--highlight,
  .chartlist-now-scrobbling,
  .chartlist-row--now-scrobbling:hover,
  .chartlist-row--highlight:hover {
    background: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
  }
  .chartlist-row--now-scrobbling td,
  .chartlist-row--now-scrobbling .chartlist-name,
  .chartlist-row--now-scrobbling .chartlist-artist,
  .chartlist-row--now-scrobbling .chartlist-album,
  .chartlist-row--now-scrobbling .chartlist-timestamp,
  .chartlist-row--highlight td,
  .chartlist-row--highlight .chartlist-name,
  .chartlist-row--highlight .chartlist-artist,
  .chartlist-row--highlight .chartlist-album,
  .chartlist-row--highlight .chartlist-timestamp {
    background: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
  }
  .chartlist-row::after, .chartlist-break::after, .shout,
  .personal-stats-item::after, .section-with-separator::after,
  .stationlink-list .stationlink::after { border-color:var(--lf-line) !important; }
  .stationlink-list .stationlink, .user-dashboard-module,
  .listening-report-brick, .listening-report-promo,
  .date-range-picker-content, .date-picker-content,
  .dropdown-menu, .modal-content, .section-settings,
  .user-dashboard-tooltip, .selectboxit-options { background-color:var(--lf-panel) !important; color:var(--lf-text) !important; }
  .date-range-picker-preset a, .date-range-picker-button,
  .dropdown-menu a, .dropdown-menu button, .stationlink-list a,
  .stationlink-list .btn, .user-dashboard-pagination-next-link,
  .user-dashboard-pagination-previous-link { color:var(--lf-text) !important; }
  .date-range-picker-preset--selected a { background-color:#383838 !important; }
  input, select, textarea, .search-field { background-color:#202020 !important; color:#fff !important; border-color:#444 !important; }
  .highcharts-background { fill:var(--lf-bg) !important; }
  .highcharts-axis-labels text, .highcharts-data-labels text { fill:var(--lf-text) !important; }
  .highcharts-grid-line { stroke:var(--lf-line) !important; }
  /* Remove remaining red/blue theme accents without affecting album artwork. */
  a, a:hover, a:focus, .mimic-link, .more-link a,
  .user-dashboard-pagination-next-link, .user-dashboard-pagination-previous-link,
  .user-dashboard-date, .user-dashboard-on-repeat-item-date,
  .header--overview .header-title-secondary a,
  .header--sub-page .header-title-secondary a { color:#fff !important; }
  .chartlist-love-button::before, .love-button,
  .header-new-love-button::before { filter: grayscale(1) brightness(2) !important; }
  .chartlist-row--now-scrobbling .chartlist-name a { color:#fff !important; }
  .header-new-love-button, .header-new-bookmark-button,
  .header-new-download-button, .header-new-more-button,
  .header-new-playlink { border-color:#fff !important; color:#fff !important; }
  .highcharts-point, .highcharts-graph { stroke:#fff !important; }
  .highcharts-series-0 rect, .highcharts-series-1 rect,
  .highcharts-series-0 path.highcharts-area { fill:#fff !important; }
  .user-dashboard-legend-item--current::before,
  .user-dashboard-section-header::after,
  .scrobble-stats-graph .user-dashboard-legend-item--current::before,
  .user-dashboard-listening-week .user-dashboard-legend-item--current::before {
    background-color:#fff !important;
  }
  /* Top Tracks: remove solid white bar boxes while keeping the ranking readable. */
  .chartlist-count-bar,
  .chartlist .countbar-bar,
  .chartlist-count-bar-slug {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
  }
  .chartlist-count-bar-value,
  .chartlist .countbar-bar-value {
    color: #eeeeee !important;
    background: transparent !important;
  }
  .chartlist--with-bar .chartlist-row:hover .chartlist-count-bar,
  .chartlist--with-bar .chartlist-row:hover .chartlist-count-bar-slug {
    background: transparent !important;
  }
  /* Preserve original Last.fm artwork, banner, header, font and spacing. */
}
